fn offset(bytes:&[u8],addr:u64)->u64{
    assert_eq!(&bytes[..6],b"\x7fELF\x02\x01");
    let u16at=|i|u16::from_le_bytes(bytes[i..i+2].try_into().unwrap())as usize;
    let u64at=|i|u64::from_le_bytes(bytes[i..i+8].try_into().unwrap());
    let ph=u64at(32)as usize;let size=u16at(54);let n=u16at(56);let mut hits=Vec::new();
    for i in 0..n{let p=ph+i*size;let ty=u32::from_le_bytes(bytes[p..p+4].try_into().unwrap());let flags=u32::from_le_bytes(bytes[p+4..p+8].try_into().unwrap());let file=u64at(p+8);let va=u64at(p+16);let len=u64at(p+32);if ty==1&&flags&1!=0&&addr>=va&&addr-va<len{hits.push(file+addr-va);}}
    assert_eq!(hits.len(),1);assert!(hits[0]<(bytes.len()as u64));hits[0]
}
